package ma.lias.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="publications")
public class Publication { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String title; @Column(length=5000) private String abstractText; @Column(length=2000) private String authors; private Integer year; @Column(name="team_id") private Long teamId; @Column(name="added_by") private Long addedBy; private String doi; @Column(name="publication_url") private String publicationUrl; @Column(name="created_at") private LocalDateTime createdAt = LocalDateTime.now(); public Long getId(){return id;} public void setId(Long id){this.id=id;} public String getTitle(){return title;} public void setTitle(String title){this.title=title;} public String getAbstractText(){return abstractText;} public void setAbstractText(String abstractText){this.abstractText=abstractText;} public String getAuthors(){return authors;} public void setAuthors(String authors){this.authors=authors;} public Integer getYear(){return year;} public void setYear(Integer year){this.year=year;} public Long getTeamId(){return teamId;} public void setTeamId(Long teamId){this.teamId=teamId;} public Long getAddedBy(){return addedBy;} public void setAddedBy(Long addedBy){this.addedBy=addedBy;} public String getDoi(){return doi;} public void setDoi(String doi){this.doi=doi;} public String getPublicationUrl(){return publicationUrl;} public void setPublicationUrl(String publicationUrl){this.publicationUrl=publicationUrl;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime createdAt){this.createdAt=createdAt;} }
